// LoadInstalledMod loads the installedModFile's InstalledMod into the .R struct
func (o *InstalledModFile) LoadInstalledMod(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.InstalledMod = nil
	o.R.Loaded.InstalledMod = false

	related, err := o.InstalledMod(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.InstalledModFiles = InstalledModFileSlice{o}

	o.R.InstalledMod = related
	o.R.Loaded.InstalledMod = true
	return nil
}

// LoadInstalledMod loads the installedModFile's InstalledMod into the .R struct
func (os InstalledModFileSlice) LoadInstalledMod(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	installedMods, err := os.InstalledMod(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.InstalledMod = nil
		o.R.Loaded.InstalledMod = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	installedModFileByKey := make(map[string][]*InstalledModFile, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		installedModFileByKey[o.InstalledModID] = append(installedModFileByKey[o.InstalledModID], o)
	}

	for _, rel := range installedMods {

		owners, ok := installedModFileByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.InstalledMod != nil {
				continue
			}

			rel.R.InstalledModFiles = append(rel.R.InstalledModFiles, o)

			o.R.InstalledMod = rel

		}
	}

	return nil
}

type installedModFileJoins[Q dialect.Joinable] struct {
	typ          string
	InstalledMod modAs[Q, installedModColumns]
}

func (j installedModFileJoins[Q]) aliasedAs(alias string) installedModFileJoins[Q] {
	return buildInstalledModFileJoins[Q](buildInstalledModFileColumns(alias), j.typ)
}

func buildInstalledModFileJoins[Q dialect.Joinable](cols installedModFileColumns, typ string) installedModFileJoins[Q] {
	return installedModFileJoins[Q]{
		typ: typ,
		InstalledMod: modAs[Q, installedModColumns]{
			c: InstalledMods.Columns,
			f: func(to installedModColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, InstalledMods.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.InstalledModID),
					))
				}

				return mods
			},
		},
	}
}
